window.CONTENT_PARTS = window.CONTENT_PARTS || [];
window.CONTENT_PARTS.push({ lang: "en", units: [
{ id: "en-actionverbs", group: "Word banks", order: 36, title: "Action verbs",
  intro: "Verbs are the engine of your story. A precise verb shows the reader exactly how something happened, so you need fewer extra words.",
  blocks: [
    { type: "text", html: "Compare <b>“He went to the door.”</b> with <b>“He tiptoed to the door.”</b> The second sentence tells us he was being careful and quiet, and we did not need a single extra word. That is the power of a precise verb." },
    { type: "tip", html: "<b>Tip:</b> When you write “walked quickly” or “said loudly”, stop and look for ONE verb that does the job of both words, such as <i>hurried</i> or <i>shouted</i>." },
    { type: "chips", title: "Verbs grouped by body part and movement", groups: [
      { title: "Hands", words: ["grabbed", "clutched", "gripped", "snatched", "fumbled", "tapped", "stroked", "patted", "squeezed", "flung", "scribbled", "rummaged", "pinched", "waved"],
        ex: "I <b>rummaged</b> through my bag, <b>fumbled</b> with the zip and finally <b>clutched</b> my EZ-Link card.", note: "Clutch and grip show you are holding on tightly, often because you are worried." },
      { title: "Feet and legs", words: ["stomped", "tiptoed", "trudged", "strolled", "marched", "shuffled", "stumbled", "sprinted", "skipped", "limped", "hopped", "dashed", "plodded", "paced"],
        ex: "After the long hike, we <b>trudged</b> back to the car park, while Jun Hao <b>limped</b> behind with a blister on his heel.", note: "Each of these verbs also shows a mood. Stomp is angry, skip is happy, trudge is tired." },
      { title: "Eyes", words: ["glanced", "peered", "stared", "glared", "squinted", "gazed", "peeked", "scanned", "blinked", "winked", "gaped", "watched", "studied"],
        ex: "Aisha <b>squinted</b> at the tiny print, then <b>glanced</b> up and <b>glared</b> at her brother for hiding her glasses.", note: "Glance is quick, gaze is long and dreamy, glare is angry." },
      { title: "Mouth and voice", words: ["whispered", "muttered", "mumbled", "stammered", "yelled", "bellowed", "shrieked", "giggled", "sighed", "gasped", "groaned", "snapped", "pleaded", "chuckled"],
        ex: "“I-I didn’t break it,” Wei Ming <b>stammered</b>, while his sister <b>giggled</b> behind the sofa.", note: "Use these instead of “said” when the way something is said matters." },
      { title: "Head and face", words: ["nodded", "frowned", "grinned", "smirked", "winced", "pouted", "scowled", "beamed", "flinched", "blushed", "yawned", "sniffed", "bit (my lip)"],
        ex: "When the nurse held up the needle, I <b>winced</b> and <b>bit my lip</b>, but Grandma just <b>beamed</b> at me.", note: "Face verbs are a quick way to show a feeling without naming it." },
      { title: "Whole body", words: ["leapt", "crouched", "slumped", "sprawled", "huddled", "wriggled", "shivered", "trembled", "staggered", "collapsed", "stretched", "tumbled", "lunged", "dived"],
        ex: "The moment the bell rang, I <b>slumped</b> in my chair, <b>stretched</b> my arms and let out a long sigh.", note: "Slump and collapse show tiredness or sadness; leap and lunge show energy." },
      { title: "Quiet movements", words: ["crept", "slipped", "sneaked", "edged", "inched", "drifted", "glided", "hovered", "lingered", "nestled", "settled", "eased"],
        ex: "I <b>crept</b> past Dad’s room, <b>eased</b> the fridge door open and <b>slipped</b> the last slice of cake onto a plate.", note: "Perfect for suspense scenes or when someone is trying not to be noticed." },
      { title: "Fast movements", words: ["darted", "dashed", "raced", "zoomed", "bolted", "scrambled", "hurtled", "whizzed", "scurried", "swooped", "sped", "charged", "rushed", "flew"],
        ex: "A cat <b>darted</b> out from the void deck and <b>bolted</b> across the road, and I <b>scrambled</b> after it.", note: "Short sentences with fast verbs make an action scene feel quick." }
    ] },
    { type: "mcq", title: "Choose the most precise verb", intro: "All three verbs could make sense, but only one fits the clues in the sentence best.", items: [
      { q: "Tired after the cross-country race, Priya ____ up the stairs to her flat, one heavy step at a time.", o: ["skipped", "trudged", "darted"], a: 1, e: "“Tired” and “one heavy step at a time” tell us she walked slowly and wearily: trudged." },
      { q: "The baby was asleep, so I ____ across the room without making a sound.", o: ["stomped", "marched", "tiptoed"], a: 2, e: "You tiptoe when you do not want to make a noise." },
      { q: "“Give that back right now!” Mei Ling ____, her face red with anger.", o: ["snapped", "whispered", "mumbled"], a: 0, e: "She is angry and speaking sharply, so “snapped” fits. Whispering and mumbling are too soft." },
      { q: "I ____ at the whiteboard because I had forgotten my glasses at home.", o: ["glanced", "squinted", "winked"], a: 1, e: "People squint, narrowing their eyes, when they cannot see clearly." },
      { q: "When the thunder boomed, the kitten ____ under the sofa and refused to come out.", o: ["strolled", "scurried", "paraded"], a: 1, e: "A frightened kitten moves quickly in short steps to hide: scurried." },
      { q: "Grandpa ____ the old photograph gently, as if it might break.", o: ["stroked", "grabbed", "flung"], a: 0, e: "“Gently” is the clue. Grabbing and flinging are rough." },
      { q: "The goalkeeper ____ to his left and caught the ball just before it crossed the line.", o: ["drifted", "dived", "inched"], a: 1, e: "A goalkeeper throws his body quickly through the air: he dives." },
      { q: "When the teacher announced a surprise spelling test, the whole class ____.", o: ["groaned", "cheered", "giggled"], a: 0, e: "Most pupils are not happy about a surprise test, so a groan shows their unhappiness." },
      { q: "Jun Hao ____ through the crowded hawker centre, looking for an empty table.", o: ["weaved", "zoomed", "collapsed"], a: 0, e: "To weave is to move in and out between things, which is what you do in a crowd." },
      { q: "After losing the final, Wei Ming ____ on the bench with his head in his hands.", o: ["leapt", "slumped", "pranced"], a: 1, e: "“Slumped” shows he sat down heavily, feeling sad and defeated." },
      { q: "The smoke alarm went off and we ____ out of the kitchen.", o: ["lingered", "strolled", "rushed"], a: 2, e: "An alarm means danger, so you move quickly: rushed." },
      { q: "Aisha ____ through her drawer, tossing out socks and pencils, until she found the missing key.", o: ["peeked", "rummaged", "patted"], a: 1, e: "To rummage is to search untidily through a lot of things." }
    ] }
  ] },
{ id: "en-adjectives", group: "Word banks", order: 37, title: "Describing words",
  intro: "Adjectives paint pictures in the reader’s mind. Use these lists to go beyond “nice”, “big” and “red”, and climb the ladders to find stronger words.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> One sharp adjective beats three blurry ones. “A <i>rusty</i> bicycle” tells us more than “an old, ugly, bad bicycle”. Choose carefully and do not pile them up." },
    { type: "chips", title: "Adjectives for every sense", groups: [
      { title: "Colours (beyond the basics)", words: ["crimson", "scarlet", "maroon", "coral", "amber", "golden", "mustard", "lime", "emerald", "olive", "turquoise", "navy", "violet", "lilac", "ivory", "charcoal"],
        ex: "The sky turned from <b>amber</b> to <b>violet</b> as the sun sank behind the HDB blocks.", note: "Pick a colour that also matches the mood: crimson feels dramatic, lilac feels gentle." },
      { title: "Textures", words: ["silky", "fluffy", "velvety", "rough", "bumpy", "prickly", "slimy", "sticky", "gritty", "crumbly", "smooth", "spongy", "scaly", "leathery"],
        ex: "The starfish at the touch pool felt <b>bumpy</b> and <b>leathery</b>, not <b>slimy</b> as I had expected.", note: "Texture words make the sense of touch come alive." },
      { title: "Sizes", words: ["tiny", "minute", "pocket-sized", "petite", "slender", "bulky", "hefty", "massive", "towering", "gigantic", "enormous", "colossal", "vast", "immense"],
        ex: "A <b>towering</b> crane stood beside the new block, making the workers below look <b>tiny</b>.", note: "Towering is for tall things; vast is for wide spaces like the sea or sky." },
      { title: "Shapes", words: ["round", "oval", "square", "triangular", "rectangular", "curved", "crooked", "jagged", "pointed", "spiral", "lopsided", "twisted", "flat", "hollow"],
        ex: "The <b>lopsided</b> birthday cake leaned to one side, but its <b>spiral</b> of icing was perfect.", note: "Jagged and pointed help in suspense; lopsided and crooked are useful for funny scenes." },
      { title: "Sounds", words: ["deafening", "piercing", "shrill", "booming", "thunderous", "muffled", "faint", "hushed", "crackling", "rumbling", "screeching", "tinkling", "melodious", "hoarse"],
        ex: "A <b>shrill</b> whistle cut through the <b>muffled</b> chatter in the hall.", note: "Faint and hushed for quiet scenes; deafening and thunderous for loud ones." },
      { title: "Smells", words: ["fragrant", "sweet-smelling", "aromatic", "smoky", "spicy", "fresh", "musty", "damp", "stale", "sour", "pungent", "rotten", "fishy", "flowery"],
        ex: "The kitchen was <b>fragrant</b> with pandan, but the storeroom smelt <b>musty</b> and <b>damp</b>.", note: "Smell is the sense most children forget. Add one smell to every setting." },
      { title: "Tastes", words: ["sweet", "sugary", "salty", "sour", "tangy", "bitter", "spicy", "fiery", "savoury", "bland", "zesty", "creamy", "juicy", "rich"],
        ex: "The <b>tangy</b> lime juice cut through the <b>fiery</b> sambal on my nasi lemak.", note: "Taste words work best when you also describe the eater’s reaction." },
      { title: "Light", words: ["bright", "dazzling", "glaring", "glowing", "glittering", "shimmering", "sparkling", "flickering", "dim", "gloomy", "shadowy", "murky", "pitch-dark", "golden"],
        ex: "A <b>flickering</b> torch lit up the <b>gloomy</b> stairwell when the lights went out.", note: "Light words set the mood instantly: glowing is cosy, shadowy is eerie." }
    ] },
    { type: "table", title: "20 adjective ladders", head: ["Plain", "Stronger", "Strongest"], rows: [
      ["big", "huge", "colossal"],
      ["small", "tiny", "microscopic"],
      ["hot", "scorching", "blistering"],
      ["cold", "icy", "bone-chilling"],
      ["tired", "weary", "exhausted"],
      ["hungry", "starving", "ravenous"],
      ["loud", "booming", "deafening"],
      ["quiet", "hushed", "silent"],
      ["pretty", "beautiful", "breathtaking"],
      ["ugly", "hideous", "grotesque"],
      ["dirty", "grimy", "filthy"],
      ["clean", "spotless", "gleaming"],
      ["bright", "brilliant", "dazzling"],
      ["dark", "gloomy", "pitch-black"],
      ["fast", "speedy", "lightning-fast"],
      ["slow", "sluggish", "painfully slow"],
      ["tasty", "delicious", "mouth-watering"],
      ["strange", "bizarre", "mind-boggling"],
      ["funny", "hilarious", "side-splitting"],
      ["scary", "frightening", "spine-chilling"]
    ] },
    { type: "tip", html: "<b>Tip:</b> The strongest word is not always the best word. A tiny scratch on your knee is not “agonising”. Pick the step on the ladder that matches what really happened." }
  ] },
{ id: "en-topicvocab", group: "Word banks", order: 38, title: "Topic vocabulary",
  intro: "Different compositions need different words. Before you write about sports day, a festival or an accident, look up the right topic here and borrow a few precise words.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Do not try to squeeze in every word. Choose three or four that fit your story naturally. A few exact words show the reader you really know the scene." },
    { type: "chips", title: "School and CCA", groups: [
      { title: "School and CCA", words: ["assembly", "form teacher", "flag-raising ceremony", "recess", "canteen", "school hall", "worksheet", "spelling test", "class monitor", "prefect", "CCA session", "rehearsal", "badge", "show-and-tell", "group project", "parent-teacher meeting"],
        ex: "After the <b>flag-raising ceremony</b>, our <b>form teacher</b> marched us back to class for a <b>spelling test</b>." }
    ] },
    { type: "chips", title: "Sports day and competitions", groups: [
      { title: "Sports day and competitions", words: ["starting line", "baton", "relay race", "track", "heat", "final", "spectators", "cheering squad", "finishing line", "neck and neck", "personal best", "podium", "medal", "trophy", "runner-up", "sportsmanship"],
        ex: "The two runners were <b>neck and neck</b> as they raced towards the <b>finishing line</b>, while the <b>spectators</b> roared." }
    ] },
    { type: "chips", title: "Singapore festivals", groups: [
      { title: "Chinese New Year", words: ["reunion dinner", "red packets", "hongbao", "mandarin oranges", "pineapple tarts", "bak kwa", "lion dance", "cymbals", "firecrackers", "lanterns", "visiting relatives", "spring cleaning", "lo hei", "new clothes"],
        ex: "At the <b>reunion dinner</b>, we tossed the <b>lo hei</b> high and shouted good wishes for the new year." },
      { title: "Hari Raya Puasa", words: ["fasting month", "Ramadan", "breaking fast", "Geylang Serai bazaar", "ketupat", "rendang", "kuih", "baju kurung", "baju Melayu", "duit raya", "seeking forgiveness", "visiting", "pelita lamps", "festive lights"],
        ex: "On the morning of Hari Raya, Aisha <b>sought forgiveness</b> from her grandparents before we tucked into <b>ketupat</b> and <b>rendang</b>." },
      { title: "Deepavali", words: ["Festival of Lights", "oil lamps", "diyas", "rangoli", "kolam", "Little India", "light-up", "murukku", "sweets", "saree", "garlands", "prayers", "fireworks", "good over evil"],
        ex: "Priya and I knelt on the floor, pouring coloured rice to make a bright <b>kolam</b> beside the flickering <b>oil lamps</b>." },
      { title: "Christmas", words: ["Orchard Road light-up", "Christmas tree", "tinsel", "baubles", "carols", "stockings", "wrapping paper", "gift exchange", "log cake", "turkey", "Secret Santa", "Christmas Eve", "midnight service", "festive spirit"],
        ex: "We strolled along the <b>Orchard Road light-up</b>, humming <b>carols</b> and pointing at the giant <b>baubles</b>." },
      { title: "Mid-Autumn Festival", words: ["mooncakes", "snow-skin mooncakes", "lotus paste", "salted egg yolk", "lanterns", "lantern walk", "full moon", "Chang’e", "pomelo", "tea", "lantern riddles", "candlelight", "Chinatown", "Gardens by the Bay"],
        ex: "Holding our paper <b>lanterns</b>, we gazed at the <b>full moon</b> and shared a <b>snow-skin mooncake</b>." }
    ] },
    { type: "chips", title: "Nature and animals", groups: [
      { title: "Nature and animals", words: ["nature reserve", "boardwalk", "mangrove", "canopy", "undergrowth", "trail", "monitor lizard", "long-tailed macaque", "otters", "kingfisher", "chirping", "rustling leaves", "dragonfly", "mudflat", "habitat", "endangered"],
        ex: "On the <b>boardwalk</b> at Sungei Buloh, a <b>monitor lizard</b> slid into the <b>mangrove</b> while a <b>kingfisher</b> flashed past." }
    ] },
    { type: "chips", title: "Accidents and emergencies", groups: [
      { title: "Accidents and emergencies", words: ["slipped", "tripped", "grazed", "sprained", "bruise", "bleeding", "first-aid kit", "plaster", "ice pack", "dialled 995", "ambulance", "paramedics", "stretcher", "fire alarm", "evacuated", "calm and steady"],
        ex: "Mum pressed an <b>ice pack</b> on my <b>sprained</b> ankle while my brother fetched the <b>first-aid kit</b>.", note: "Keep accident stories focused on how people helped and what was learnt, not on gory details." }
    ] },
    { type: "chips", title: "Family outings and travel", groups: [
      { title: "Family outings and travel", words: ["itinerary", "packed lunch", "picnic mat", "East Coast Park", "cycling path", "boarding pass", "check-in counter", "departure hall", "luggage", "souvenir", "sightseeing", "chalet", "scenic", "queue", "tour guide", "jet lag"],
        ex: "After checking our <b>luggage</b> at the <b>check-in counter</b>, we raced to the <b>departure hall</b> to watch the planes." }
    ] },
    { type: "chips", title: "Technology and games", groups: [
      { title: "Technology and games", words: ["tablet", "laptop", "charger", "password", "screen time", "level up", "high score", "controller", "glitch", "download", "online lesson", "video call", "notification", "cyberbully", "privacy", "log out"],
        ex: "Just as I was about to beat my <b>high score</b>, the screen froze with a <b>glitch</b> and the battery died." }
    ] },
    { type: "chips", title: "Home and chores", groups: [
      { title: "Home and chores", words: ["mop", "broom", "dustpan", "vacuum", "sweep", "wipe", "fold the laundry", "hang the clothes", "wash the dishes", "water the plants", "take out the rubbish", "rubbish chute", "corridor", "spotless", "household", "pitch in"],
        ex: "Every Saturday, the whole family <b>pitches in</b>: I <b>sweep</b> the floor, my sister <b>wipes</b> the windows and Dad takes the bags to the <b>rubbish chute</b>." }
    ] }
  ] },
{ id: "en-flash", group: "Word banks", order: 39, title: "Vocabulary flashcards",
  intro: "Over sixty useful words for upper primary writers. Read the word, try to explain it in your head, then flip the card to check.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Do ten cards a day. When you know a word, try to use it in your next composition or in your diary. A word you have used once is a word you will remember." },
    { type: "flash", title: "60 words to know", intro: "Tap a card to flip it. Mark it if you knew the meaning before you flipped.", items: [
      { f: "reluctant", b: "Not wanting to do something.<br><i>Wei Ming was reluctant to jump into the deep end of the pool.</i>" },
      { f: "anxious", b: "Worried and nervous about what might happen.<br><i>I felt anxious as I waited for my name to be called.</i>" },
      { f: "astonished", b: "Very surprised.<br><i>Mum was astonished to see the kitchen spotless.</i>" },
      { f: "bewildered", b: "Very confused.<br><i>The new pupil looked bewildered as she searched for the science lab.</i>" },
      { f: "determined", b: "Having made a firm decision and not giving up.<br><i>Determined to finish the race, Priya kept running despite the stitch in her side.</i>" },
      { f: "furious", b: "Extremely angry.<br><i>Dad was furious when he saw the dent in the car door.</i>" },
      { f: "grateful", b: "Feeling thankful for something someone did.<br><i>I was grateful to the cleaner who found my water bottle.</i>" },
      { f: "hesitate", b: "To pause before doing something because you are unsure.<br><i>I hesitated at the door before knocking.</i>" },
      { f: "humble", b: "Not thinking you are better than others.<br><i>Even after winning gold, Jun Hao stayed humble and thanked his coach.</i>" },
      { f: "considerate", b: "Thinking about other people’s feelings and needs.<br><i>It was considerate of Aisha to lower her voice in the library.</i>" },
      { f: "generous", b: "Happy to give or share.<br><i>Grandma is generous and always packs extra kuih for my friends.</i>" },
      { f: "selfish", b: "Caring only about yourself.<br><i>It was selfish of me to finish the snacks without asking my sister.</i>" },
      { f: "mischievous", b: "Playfully naughty.<br><i>My mischievous cousin hid my slippers under the sofa.</i>" },
      { f: "cautious", b: "Careful to avoid danger or mistakes.<br><i>We were cautious as we crossed the slippery rocks.</i>" },
      { f: "frantic", b: "Wild and desperate because of fear or worry.<br><i>Mum was frantic when she could not find her phone just before we left.</i>" },
      { f: "exhausted", b: "Extremely tired.<br><i>After the cross-country run, I was too exhausted to talk.</i>" },
      { f: "relieved", b: "Feeling better because a worry has gone away.<br><i>I was relieved when the doctor said it was only a sprain.</i>" },
      { f: "embarrassed", b: "Feeling shy or silly in front of others.<br><i>I was embarrassed when I tripped on the stage steps.</i>" },
      { f: "envious", b: "Wanting something that someone else has.<br><i>I felt envious when I saw Ben’s new bicycle.</i>" },
      { f: "remorse", b: "A deep feeling of being sorry for something wrong you did.<br><i>Full of remorse, I apologised to Mei Ling for breaking her ruler.</i>" },
      { f: "dilemma", b: "A difficult choice between two things.<br><i>I faced a dilemma: tell the truth or protect my friend.</i>" },
      { f: "consequence", b: "Something that happens as a result of an action.<br><i>Losing my CCA place was the consequence of skipping practice.</i>" },
      { f: "opportunity", b: "A good chance to do something.<br><i>The school trip was an opportunity to see a real mangrove.</i>" },
      { f: "responsibility", b: "A duty you are trusted to carry out.<br><i>Feeding the class fish was my responsibility this week.</i>" },
      { f: "confidence", b: "A feeling that you can do something well.<br><i>Practising every day gave me the confidence to sing on stage.</i>" },
      { f: "courage", b: "Being brave even when you are scared.<br><i>It took courage to tell the teacher what had happened.</i>" },
      { f: "persevere", b: "To keep trying even when it is hard.<br><i>She persevered with the puzzle until every piece fitted.</i>" },
      { f: "encourage", b: "To give someone hope or confidence.<br><i>My teammates encouraged me after I missed the goal.</i>" },
      { f: "apologise", b: "To say sorry.<br><i>I apologised to the auntie for bumping into her tray.</i>" },
      { f: "recognise", b: "To know someone or something because you have seen it before.<br><i>I recognised my old kindergarten teacher at the MRT station.</i>" },
      { f: "realise", b: "To suddenly understand or notice something.<br><i>I realised I had left my homework on the bus.</i>" },
      { f: "glimpse", b: "A quick look at something.<br><i>I caught a glimpse of an otter before it slipped into the water.</i>" },
      { f: "commotion", b: "Noisy excitement or confusion.<br><i>There was a commotion at the void deck when a snake appeared.</i>" },
      { f: "chaos", b: "Complete confusion and disorder.<br><i>When the fire alarm rang, the canteen fell into chaos.</i>" },
      { f: "deserted", b: "Empty, with no people around.<br><i>The playground was deserted after the heavy rain.</i>" },
      { f: "crowded", b: "Full of people.<br><i>The MRT train was so crowded that I could not move my arms.</i>" },
      { f: "spotless", b: "Perfectly clean.<br><i>After two hours of cleaning, the flat was spotless.</i>" },
      { f: "fragile", b: "Easily broken.<br><i>Carry the vase carefully, because it is fragile.</i>" },
      { f: "enormous", b: "Very large.<br><i>An enormous rain tree shaded the whole car park.</i>" },
      { f: "ancient", b: "Very old.<br><i>Grandpa opened an ancient biscuit tin full of letters.</i>" },
      { f: "eerie", b: "Strange and slightly frightening.<br><i>An eerie silence filled the corridor at night.</i>" },
      { f: "vivid", b: "Very bright and clear, or easy to picture.<br><i>I still have a vivid memory of my first day in Primary One.</i>" },
      { f: "gradually", b: "Slowly, little by little.<br><i>Gradually, the dark clouds drifted away.</i>" },
      { f: "immediately", b: "At once, without waiting.<br><i>When Mum called, I immediately switched off the computer.</i>" },
      { f: "reluctantly", b: "In an unwilling way.<br><i>I reluctantly handed over my phone at bedtime.</i>" },
      { f: "eventually", b: "In the end, after a long time.<br><i>Eventually, the bus arrived, twenty minutes late.</i>" },
      { f: "suddenly", b: "Quickly and without warning.<br><i>Suddenly, the lights went out.</i>" },
      { f: "anticipate", b: "To expect something and get ready for it.<br><i>We anticipated rain, so we packed umbrellas.</i>" },
      { f: "accompany", b: "To go somewhere with someone.<br><i>I accompanied Grandma to the market every Sunday.</i>" },
      { f: "admire", b: "To look up to someone or think highly of them.<br><i>I admire my coach for never giving up on us.</i>" },
      { f: "comfort", b: "To make someone feel less sad or worried.<br><i>I sat beside Ali and tried to comfort him.</i>" },
      { f: "console", b: "To comfort someone who is sad or disappointed.<br><i>We consoled our goalkeeper after the match.</i>" },
      { f: "scold", b: "To speak angrily to someone because they did something wrong.<br><i>Mum scolded me for coming home late.</i>" },
      { f: "insist", b: "To say firmly that something must happen.<br><i>Dad insisted that we wear our helmets.</i>" },
      { f: "confess", b: "To admit you did something wrong.<br><i>I finally confessed that I had broken the remote control.</i>" },
      { f: "volunteer", b: "To offer to do something without being asked or paid.<br><i>Priya volunteered to help at the old folks’ home.</i>" },
      { f: "trudge", b: "To walk slowly and heavily, usually when tired.<br><i>We trudged home in the rain.</i>" },
      { f: "glare", b: "To stare angrily.<br><i>The librarian glared at the noisy boys.</i>" },
      { f: "plead", b: "To beg someone in an emotional way.<br><i>“Please let me stay up a bit longer,” I pleaded.</i>" },
      { f: "resilient", b: "Able to recover quickly after a difficulty.<br><i>Although she lost the first round, the resilient swimmer won the next.</i>" },
      { f: "integrity", b: "Being honest and doing the right thing even when no one is watching.<br><i>Returning the extra change showed his integrity.</i>" },
      { f: "empathy", b: "Understanding how someone else feels.<br><i>Because she had once been new too, Aisha showed empathy to the new girl.</i>" }
    ] }
  ] },
{ id: "en-warmups", group: "Practice", order: 55, title: "Daily warm-ups",
  intro: "Just like athletes stretch before a race, writers warm up too. Pick one prompt a day, write for five minutes, then compare with the model.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Set a timer for five minutes. Do not worry about being perfect. The goal is to get your writing muscles moving. The model is just one good answer, not the only one." },
    { type: "rewrite", title: "30 five-minute warm-ups", intro: "Read the prompt, write your answer, then reveal the model.", items: [
      { q: "Describe the smell of a hawker centre at lunchtime in two sentences.", a: "The air was thick with the smoky smell of charcoal-grilled satay and the sweet scent of kaya toast. Every few steps, a new smell drifted over me, from tangy lime to fragrant chicken rice.", hint: "Name at least two different foods." },
      { q: "Write ONE sentence that uses three senses.", a: "As the thunder rumbled overhead, I wrapped my cold fingers around a mug of hot Milo and breathed in its rich, chocolatey smell.", hint: "Hearing, touch and smell work well together." },
      { q: "Show that a character is nervous without using the word “nervous”.", a: "Jun Hao wiped his sweaty palms on his shorts for the third time and stared at the door of the exam hall.", hint: "Think about hands, eyes and breathing." },
      { q: "Write a line of dialogue for a grandmother who is proud of her grandchild.", a: "“Look at you, so tall already!” Grandma said, patting my cheek. “Soon you’ll be taller than your father.”", hint: "Let her voice sound real and warm." },
      { q: "Describe the sound of heavy rain on the roof of a bus shelter.", a: "The rain drummed on the metal roof like a thousand tiny fingers, so loud that I could not hear my friend shouting beside me." },
      { q: "Write two sentences about your favourite place without naming it. Let the reader guess.", a: "Rows of colourful spines stand shoulder to shoulder on tall shelves, and the only sound is the soft flutter of pages. I can travel to a hundred worlds here without leaving my seat.", hint: "The answer here is a library." },
      { q: "Show that someone is angry using only actions.", a: "Mei Ling slammed her bag on the table, folded her arms and refused to look at anyone." },
      { q: "Write a sentence that starts with a sound word.", a: "Crash! The tray of plates slipped from the waiter’s hands and shattered on the floor." },
      { q: "Describe a cat using a simile.", a: "The ginger cat stretched across the warm void deck floor like a lazy orange rug." },
      { q: "Write a sentence about waiting that makes time feel slow.", a: "The minute hand crawled around the clock while I sat outside the principal’s office, counting every tick." },
      { q: "Describe the moment just before a race starts.", a: "I crouched at the starting line, my fingers pressed against the hot track. The whole stadium seemed to hold its breath, waiting for the whistle." },
      { q: "Write three sentences that each start in a different way.", a: "Clutching my umbrella, I stepped into the storm. Within seconds, my shoes were soaked. Water dripped from my fringe into my eyes.", hint: "Try an -ing word, a time phrase and a noun." },
      { q: "Show that a character is happy without using the word “happy”.", a: "Aisha skipped down the corridor, humming loudly and swinging her report book like a prize." },
      { q: "Describe the taste of something sour.", a: "The moment I bit into the green mango, my whole face scrunched up and my eyes began to water." },
      { q: "Write a line of dialogue that shows someone is in a hurry.", a: "“Quick, quick! The bus is coming!” Dad shouted, already halfway out of the door with one shoe on." },
      { q: "Describe your classroom using the sense of hearing only.", a: "Pencils scratched across paper, a fan whirred lazily above us, and somewhere at the back, someone was trying very hard not to sneeze." },
      { q: "Turn this into a show sentence: “The boy was cold.”", a: "The boy hugged his arms tightly and his teeth chattered as the air-conditioner blasted icy air over him." },
      { q: "Write a sentence with a personification about the wind.", a: "The wind howled through the corridor and tugged at the posters on the noticeboard." },
      { q: "Describe a person’s face in two sentences so the reader can picture them.", a: "Grandpa’s face was as wrinkled as a crumpled paper bag, but his eyes twinkled behind his thick round glasses. When he laughed, his whole moustache wobbled." },
      { q: "Write an opening sentence that asks the reader a question.", a: "Have you ever wished you could take back something the moment you said it?" },
      { q: "Describe the moment something falls and breaks, in slow motion.", a: "The glass slid off the edge of the table. It turned once, twice, catching the light, and then shattered into a hundred glittering pieces on the floor." },
      { q: "Write two sentences that show a character is shy.", a: "Priya hid behind her mother’s skirt and peeped out at the other children. When the teacher said hello, she stared at her shoes and whispered her name." },
      { q: "Write a sentence using “Although” to show two feelings at once.", a: "Although I was sad to leave my old school, I was secretly excited to make new friends." },
      { q: "Describe a smell that brings back a memory.", a: "The scent of pandan cake drifting from the kitchen took me straight back to Grandma’s flat on Sunday afternoons." },
      { q: "Write the last sentence of a story about learning a lesson.", a: "Now, before I leave the house, I pat my pocket twice. I still remember the cold, empty feeling of the day it was not there." },
      { q: "Describe a busy MRT station in three short sentences.", a: "People streamed through the gantries. Beeps and announcements filled the air. Everyone seemed to be in a hurry except the pigeon by the exit." },
      { q: "Show that a character is tired, using a simile.", a: "By the end of the hike, my legs felt as heavy as sacks of rice, and I dragged my feet like a tired old tortoise." },
      { q: "Write a dialogue line where one friend comforts another.", a: "“It’s just one test,” Wei Ming said softly, resting a hand on my shoulder. “We’ll study together for the next one.”" },
      { q: "Describe the sky at sunset in one sentence with two colours.", a: "The sky blazed orange above the sea, slowly melting into a soft purple as the sun slipped away." },
      { q: "Write a sentence that builds suspense by ending with a surprise.", a: "I reached into the dark cupboard for my torch, and my fingers touched something warm, furry and moving." }
    ] }
  ] },
{ id: "en-starters", group: "Practice", order: 56, title: "Story starters",
  intro: "Here are thirty opening lines. Choose one and keep the story going for three to five sentences. Then compare with the model continuation.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> After the first line, ask yourself: Who is here? What do they want? What goes wrong? Let your next sentences answer at least one of these questions." },
    { type: "rewrite", title: "30 opening lines", intro: "Continue the story for three to five sentences.", items: [
      { q: "The lift doors opened, but the lift was not there.", a: "I froze, staring into the dark shaft and hearing the cables creak far below. Behind me, my little brother was still playing on his tablet, not looking up. I pulled him back by his collar and pressed the alarm button on the wall. Within minutes, the security guard came running, his face pale." },
      { q: "Nobody had touched the old piano in the hall for years, so why was it playing?", a: "Mei Ling and I crept towards the stage, clutching each other’s arms. The notes were soft and slow, like a lullaby. When we peeked behind the curtain, we found our new classmate, Tom, playing with his eyes closed. He jumped when he saw us, and his cheeks turned bright red." },
      { q: "The moment I opened my lunch box, I knew Mum had given me the wrong one.", a: "Instead of my usual sandwich, there were four sticks of satay and a neat pile of ketupat. It was Dad’s lunch for his office potluck! I pictured him opening my box of jam sandwiches in front of his colleagues, and I burst out laughing. That evening, Dad said the sandwiches were not bad at all, but I had decided that satay was much better." },
      { q: "“Don’t press that button!” shouted my brother, but it was too late.", a: "A loud beep echoed through the kitchen, and the rice cooker lid flew open. A cloud of steam shot up to the ceiling. We stared at the half-cooked rice, then at each other. “Mum is going to be home in ten minutes,” he whispered." },
      { q: "The postman handed me a parcel with my name on it, but I had not ordered anything.", a: "It was wrapped in brown paper and tied with a red string. Inside was a small wooden box and a note in shaky handwriting: “For my favourite grandchild.” I recognised Grandpa’s writing at once. It was the old pocket watch he had promised me years ago." },
      { q: "It was the last minute of the match, and the ball was rolling towards me.", a: "My heart pounded in my ears. I could hear my teammates screaming my name. I swung my leg back and kicked with all my might. The ball curved, hit the post and bounced in." },
      { q: "When I woke up, the whole flat was strangely quiet.", a: "There was no clatter of pots from the kitchen and no radio playing. I tiptoed into the living room and saw a note on the table. “Gone to the market. Back soon. Don’t forget to feed the fish!” I glanced at the tank and gasped. The fish were gone." },
      { q: "The new girl stood at the classroom door, holding her bag tightly.", a: "Her eyes darted from face to face as if looking for a friend. Nobody moved. Then I remembered my own first day, when I had felt exactly the same. I waved and pointed to the empty seat beside me." },
      { q: "I had never seen Dad cry before that day.", a: "He was sitting alone on the bench at the void deck, staring at his phone. When he saw me, he quickly wiped his eyes and tried to smile. “Grandma is in hospital,” he said quietly. I sat down beside him and held his hand." },
      { q: "The sky turned black in the middle of the afternoon.", a: "Lightning flashed across the field, and the teacher blew her whistle. We grabbed our bags and raced for the shelter. Just as we reached it, the rain came down in sheets. Then I realised that Ahmad was still standing in the middle of the field." },
      { q: "Somebody had written my name on the whiteboard in big red letters.", a: "Underneath it were the words: “See me after school.” My stomach twisted into a knot. All through the lessons, I tried to think of what I had done wrong. When the bell rang, I walked slowly to the staffroom, my legs feeling like jelly." },
      { q: "“Can you keep a secret?” Priya whispered.", a: "I nodded, and she pulled me behind the canteen. From her bag, she took out a tiny shoebox with holes in the lid. Inside, a baby bird blinked up at us. “I found it under the tree,” she said. “I don’t know how to look after it.”" },
      { q: "The smell of smoke drifted through the corridor.", a: "I sniffed, then ran to the window. Grey smoke was curling out of Mrs Tan’s kitchen next door. I banged on her door, but nobody answered. With shaking hands, I dialled 995." },
      { q: "Grandpa said the old biscuit tin must never be opened.", a: "For years, it sat on top of his wardrobe, gathering dust. One rainy afternoon, curiosity got the better of me. I climbed onto a chair and lifted the lid. Inside were dozens of letters, all addressed to Grandma." },
      { q: "My name was the last one on the list.", a: "I read it again to make sure. I had made it into the school choir! I punched the air and let out a squeal, then quickly covered my mouth when the teachers in the office looked up. All the way home, I sang under my breath." },
      { q: "The torchlight flickered, then went out.", a: "Darkness swallowed the campsite. Somewhere nearby, a twig snapped. I held my breath and felt for my brother’s hand. “Was that you?” I whispered. He did not answer." },
      { q: "I only wanted to borrow my sister’s headphones for five minutes.", a: "But five minutes became an hour, and somehow they ended up under my pillow. The next morning, I heard a cry from her room. “Has anyone seen my headphones?” I pulled the blanket over my head and wished I could disappear." },
      { q: "The queue at the bubble tea shop was the longest I had ever seen.", a: "It snaked all the way past the bookshop and around the escalator. Mum sighed and checked her watch. “Just ten more minutes, please,” I begged. Just then, the boy in front of us turned around, and I realised it was my favourite YouTuber." },
      { q: "Our class pet, a hamster called Biscuit, was missing.", a: "His cage door was wide open and his food bowl was empty. Everyone dropped to their knees to search under desks and cupboards. Then I heard a tiny rustle from the teacher’s bag. Slowly, a pink nose poked out from between the worksheets." },
      { q: "I stared at the empty space where my bicycle should have been.", a: "The lock lay cut in two on the ground. Anger rose in my chest, and then something worse: fear of telling Dad. It had been my birthday present. I took a deep breath and walked to the security post." },
      { q: "“Ladies and gentlemen, please welcome our next performer!”", a: "The spotlight swung towards me, so bright that I could not see the audience. My fingers trembled on the violin. I closed my eyes and pictured my bedroom, where I had practised every night. Then I lifted the bow and began to play." },
      { q: "The old man at the bus stop looked lost.", a: "He kept turning a crumpled piece of paper in his hands and peering at the bus numbers. People hurried past without looking at him. I stepped closer. “Uncle, can I help you?” I asked." },
      { q: "I knew I should not have climbed the tree.", a: "Now I was sitting on a branch far above the ground, and it was creaking under me. My kite was still tangled in the leaves just out of reach. Below, my friends had stopped laughing. “Don’t move!” one of them called." },
      { q: "The fire alarm rang in the middle of our maths test.", a: "Chairs scraped and pencils clattered to the floor. Our teacher calmly told us to line up and walk, not run, to the field. As we marched out, I glanced back at my unfinished test paper. For once, I was glad of a fire drill." },
      { q: "There was a strange footprint on our kitchen floor.", a: "It was small and muddy, with five long, thin toes. My sister and I crouched down to look at it. Another one was by the door, and another by the window. We followed the trail and found a very guilty-looking monitor lizard behind the rubbish bin." },
      { q: "The first day of the school holidays started with a disaster.", a: "I had planned to sleep until noon, but at seven o’clock, water began dripping onto my face. The upstairs neighbour’s pipe had burst. Within minutes, my room was a pool of water. My holiday had begun with a mop instead of a pillow." },
      { q: "“I bet you can’t do it,” Daniel said with a smirk.", a: "Everyone turned to look at me. The wall was high and the ground below was rough concrete. My heart told me to prove him wrong, but my head told me something else. I shook my head and walked away, and that was the bravest thing I did all week." },
      { q: "Everything was going perfectly until the cake started to slide.", a: "I watched in horror as the three tiers tilted to one side. I leapt forward and caught the top layer just in time, but cream splattered all over my shirt. Behind me, the birthday girl burst into giggles. Soon, everyone was laughing, including me." },
      { q: "The note in my desk said only: “Meet me at the library at recess.”", a: "There was no name, just a small drawing of a star. All morning, I tried to guess who had written it. When the bell rang, I hurried to the library. Sitting in the corner was Mei Ling, holding a birthday card with my name on it." },
      { q: "The waves were getting bigger, and the shore was getting further away.", a: "I kicked hard, but the current kept pulling me back. Salt water stung my eyes. I waved both arms above my head, just as the lifeguard had taught us. A whistle shrieked from the beach, and a figure in red raced into the water." }
    ] }
  ] },
{ id: "en-editpara", group: "Practice", order: 57, title: "Edit the paragraph",
  intro: "Good writers always check their work. Each paragraph below has three to five mistakes. Find them, write the corrected paragraph, then check the list of fixes.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Read the paragraph three times, looking for one kind of mistake each time: first <b>spelling</b>, then <b>tense</b>, then <b>punctuation and capital letters</b>. Reading it aloud in a whisper helps you hear missing full stops." },
    { type: "fixit", title: "Find and fix the mistakes", intro: "Write the whole paragraph correctly, then check.", items: [
      { wrong: "Last saturday, my family went to east coast park. We cycle along the beach and stopped for a picnic. My brother forgot to bring the drinks, so we was all very thirsty.",
        right: "Last Saturday, my family went to East Coast Park. We cycled along the beach and stopped for a picnic. My brother forgot to bring the drinks, so we were all very thirsty.",
        why: "1. “Saturday” needs a capital letter (days of the week). 2. “East Coast Park” is a place name, so it needs capitals. 3. “cycle” should be past tense “cycled”. 4. “we was” should be “we were”." },
      { wrong: "“Where is your homework” asked Mum. I looked under my bed but it wasnt there. Suddenly I remembered that I leave it in the school library.",
        right: "“Where is your homework?” asked Mum. I looked under my bed, but it wasn’t there. Suddenly, I remembered that I had left it in the school library.",
        why: "1. A question needs a question mark inside the speech marks. 2. Add a comma before “but” when joining two longer clauses. 3. “wasnt” needs an apostrophe: “wasn’t”. 4. Put a comma after “Suddenly” at the start. 5. “leave” should be “had left” because it happened earlier." },
      { wrong: "The hawker centre was very crowded. Uncles and aunties shouted there orders and the smell of satay fill the air. I could’nt find an empty table anywhere.",
        right: "The hawker centre was very crowded. Uncles and aunties shouted their orders, and the smell of satay filled the air. I couldn’t find an empty table anywhere.",
        why: "1. “there” should be “their” (the orders belong to them). 2. “fill” should be past tense “filled”. 3. The apostrophe in “couldn’t” goes where the letter “o” is missing, not before the “n”." },
      { wrong: "On the first day of school, i felt very nervus. My hands was shaking as I walked into the classroom. The teacher smiled at me and say, “welcome to Primary Four.”",
        right: "On the first day of school, I felt very nervous. My hands were shaking as I walked into the classroom. The teacher smiled at me and said, “Welcome to Primary Four.”",
        why: "1. “I” is always a capital letter. 2. Spelling: “nervous”. 3. “hands” is plural, so “were”, not “was”. 4. “say” should be past tense “said”. 5. The first word inside speech marks needs a capital: “Welcome”." },
      { wrong: "Aisha and me went to the library after school. We borrowed three books about dinosaurs. When we reached home, Aisha’s mother gived us some biscuits and milk.",
        right: "Aisha and I went to the library after school. We borrowed three books about dinosaurs. When we reached home, Aisha’s mother gave us some biscuits and milk.",
        why: "1. “Aisha and me” is the subject of the sentence, so use “Aisha and I”. 2. “gived” is wrong; the past tense of “give” is “gave”. (Tip: take away “Aisha and” and check: “I went”, not “me went”.)" },
      { wrong: "Its raining heavily outside. My sister and I is stuck at the bus stop. “We should of brought an umbrella” she sighed.",
        right: "It’s raining heavily outside. My sister and I are stuck at the bus stop. “We should have brought an umbrella,” she sighed.",
        why: "1. “Its” means “it is” here, so it needs an apostrophe: “It’s”. 2. “My sister and I” is two people, so “are”. 3. “should of” is wrong; say “should have”. 4. Add a comma before the closing speech mark when the speech is followed by “she sighed”." },
      { wrong: "During recess, Jun Hao trip over a bag and fell down. His knee was bleeding. I quickly ran to get our teacher, mrs lim, who brought the first aid kit.",
        right: "During recess, Jun Hao tripped over a bag and fell down. His knee was bleeding. I quickly ran to get our teacher, Mrs Lim, who brought the first-aid kit.",
        why: "1. “trip” should be past tense “tripped” (double the p). 2. “Mrs Lim” is a name and title, so both need capitals. 3. “first-aid kit” is usually written with a hyphen." },
      { wrong: "Every morning, Grandma wakes up at six oclock. She goes to the market to buy fresh vegetable’s. Yesterday she bought a huge durian and carry it home herself.",
        right: "Every morning, Grandma wakes up at six o’clock. She goes to the market to buy fresh vegetables. Yesterday, she bought a huge durian and carried it home herself.",
        why: "1. “o’clock” needs an apostrophe (it is short for “of the clock”). 2. Plurals do not need apostrophes: “vegetables”. 3. Add a comma after the time phrase “Yesterday”. 4. “carry” should be past tense “carried”, to match “bought”." },
      { wrong: "“Hurry up! shouted Dad. “The taxi is waiting downstairs.” I grabbed my bag and ran to the door. In my hurry, I forget to switch off the fan.",
        right: "“Hurry up!” shouted Dad. “The taxi is waiting downstairs.” I grabbed my bag and ran to the door. In my hurry, I forgot to switch off the fan.",
        why: "1. The closing speech mark is missing after “Hurry up!”. 2. “forget” should be past tense “forgot”." },
      { wrong: "The whole class was exited about the trip to the zoo. We seen orang utans, giraffes and a white tiger. Priya said it was the most best day of the year.",
        right: "The whole class was excited about the trip to the zoo. We saw orang utans, giraffes and a white tiger. Priya said it was the best day of the year.",
        why: "1. Spelling: “excited” (exited means “went out”). 2. “We seen” is wrong; use “We saw”. 3. “most best” is a double comparative; just say “best”." },
      { wrong: "My neighbour, Mr Kumar have a friendly dog called Rocky. Every evening, Rocky wait for him at the lift lobby. When the doors open, he wag his tail so hard that his whole body wiggles.",
        right: "My neighbour, Mr Kumar, has a friendly dog called Rocky. Every evening, Rocky waits for him at the lift lobby. When the doors open, he wags his tail so hard that his whole body wiggles.",
        why: "1. Add a comma after “Mr Kumar” to close the extra information. 2. “Mr Kumar” is one person, so “has”. 3. “Rocky wait” should be “Rocky waits”. 4. “he wag” should be “he wags”. (This paragraph is in the present tense because it is about something that happens every day.)" },
      { wrong: "When the lights went out, everyone screamed. “Dont panic,” said our teacher calmly, “It’s only a power cut.” A few minutes later, the lights come back on and we all cheered loudly.",
        right: "When the lights went out, everyone screamed. “Don’t panic,” said our teacher calmly. “It’s only a power cut.” A few minutes later, the lights came back on and we all cheered loudly.",
        why: "1. “Don’t” needs an apostrophe. 2. “Don’t panic” and “It’s only a power cut” are two separate sentences, so put a full stop after “calmly”, not a comma. 3. “come” should be past tense “came”." }
    ] }
  ] },
{ id: "en-quizmix", group: "Practice", order: 58, title: "Grammar and spelling quiz",
  intro: "Thirty quick questions on the mistakes pupils make most often: tricky spellings, words that sound alike, prepositions, plurals, agreement, pronouns and comparatives.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Read the whole sentence before you choose. Then read it again with your answer in place. Does it sound right?" },
    { type: "mcq", title: "Mixed quiz", intro: "Choose the correct answer.", items: [
      { q: "Which spelling is correct?", o: ["definately", "definitely", "definitly"], a: 1, e: "Definitely contains the word “finite”: de-FINITE-ly." },
      { q: "Which spelling is correct?", o: ["beautiful", "beautyful", "beatiful"], a: 0, e: "Beautiful: b-e-a-u. Remember “Big Elephants Are Usually beautiful”." },
      { q: "Which spelling is correct?", o: ["recieve", "receive", "receeve"], a: 1, e: "“i before e, except after c”: receive." },
      { q: "Which spelling is correct?", o: ["neccessary", "necesary", "necessary"], a: 2, e: "Necessary has one collar (c) and two sleeves (ss)." },
      { q: "Which spelling is correct?", o: ["tommorow", "tomorrow", "tomorow"], a: 1, e: "Tomorrow: one m, double r." },
      { q: "Which spelling is correct?", o: ["separate", "seperate", "separete"], a: 0, e: "There is “a rat” in sep-a-rat-e." },
      { q: "We left ____ bags at the void deck.", o: ["there", "their", "they’re"], a: 1, e: "“Their” shows that the bags belong to them." },
      { q: "I would like to come ____.", o: ["to", "too", "two"], a: 1, e: "“Too” means “also” here." },
      { q: "The heavy rain did not ____ our plans for the picnic.", o: ["affect", "effect", "afect"], a: 0, e: "“Affect” is usually the verb (to change something); “effect” is usually the noun (the result)." },
      { q: "Please ____ the door quietly.", o: ["clothes", "close", "closs"], a: 1, e: "Close the door. Clothes are what you wear." },
      { q: "I could not ____ which ice-cream to choose.", o: ["chose", "choose", "chews"], a: 1, e: "After “could not”, use the base verb “choose”. “Chose” is the past tense." },
      { q: "The dog wagged ____ tail happily.", o: ["it’s", "its", "its’"], a: 1, e: "“Its” shows belonging. “It’s” always means “it is” or “it has”." },
      { q: "We arrived ____ the airport at seven o’clock.", o: ["at", "on", "in"], a: 0, e: "We use “arrive at” for a particular place, such as an airport or a station." },
      { q: "My birthday is ____ March.", o: ["on", "at", "in"], a: 2, e: "Use “in” for months and years, “on” for days and dates, “at” for times." },
      { q: "Mei Ling is very good ____ drawing.", o: ["in", "at", "on"], a: 1, e: "We say “good at” something." },
      { q: "I am afraid ____ spiders.", o: ["of", "from", "with"], a: 0, e: "We say “afraid of”." },
      { q: "Wei Ming jumped ____ the swimming pool.", o: ["into", "in", "onto"], a: 0, e: "“Into” shows movement from outside to inside." },
      { q: "What is the plural of “child”?", o: ["childs", "children", "childrens"], a: 1, e: "Child is irregular: one child, two children." },
      { q: "What is the plural of “box”?", o: ["boxs", "boxes", "boxies"], a: 1, e: "Add -es to words ending in x, s, sh, ch: boxes." },
      { q: "What is the plural of “leaf”?", o: ["leafs", "leaves", "leafes"], a: 1, e: "Many words ending in f change to -ves: leaf, leaves." },
      { q: "What is the plural of “sheep”?", o: ["sheeps", "sheepes", "sheep"], a: 2, e: "Sheep stays the same: one sheep, ten sheep." },
      { q: "Neither of the boys ____ his homework.", o: ["have done", "has done", "have do"], a: 1, e: "“Neither” is singular, so it takes “has”." },
      { q: "The basket of mangoes ____ on the table.", o: ["is", "are", "were"], a: 0, e: "The subject is “the basket” (one basket), so use “is”." },
      { q: "Everybody in the class ____ excited about the trip.", o: ["are", "were", "is"], a: 2, e: "“Everybody” is singular, so use “is”." },
      { q: "Mum gave the sweets to my sister and ____.", o: ["I", "me", "myself"], a: 1, e: "After “to”, use “me”. Check by removing “my sister and”: “gave the sweets to me”." },
      { q: "____ and Priya are best friends.", o: ["Me", "Her", "She"], a: 2, e: "The subject of the sentence needs “she”: “She and Priya are best friends.”" },
      { q: "That pencil case is not mine. It is ____.", o: ["her’s", "hers", "her"], a: 1, e: "Possessive pronouns like hers, his, ours and theirs never have apostrophes." },
      { q: "This is the ____ durian I have ever eaten!", o: ["most delicious", "deliciousest", "more delicious"], a: 0, e: "Long adjectives use “most” for the superlative." },
      { q: "My brother is ____ than me.", o: ["more tall", "taller", "tallest"], a: 1, e: "Short adjectives add -er when comparing two people." },
      { q: "Today’s weather is even ____ than yesterday’s.", o: ["worse", "badder", "worst"], a: 0, e: "Bad, worse, worst. Use “worse” when comparing two things." }
    ] }
  ] },
{ id: "en-models2", group: "Model essays", order: 61, title: "More model essays",
  intro: "Five more model stories on themes that often come up: kindness, courage, mistakes, competitions and accidents. The coloured highlights show what each writer did well.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Read each essay twice. The first time, just enjoy the story. The second time, turn on the highlights and read the notes. Then pick ONE trick to borrow for your next composition." },
    { type: "essay", title: "A Kind Act", level: "P3–P4", paras: [
      "<mark class=\"s\">The MRT train was packed. Bodies pressed against me, the air-conditioner hummed above my head and someone’s umbrella dripped onto my shoe.</mark> I was squeezed into a corner seat with my school bag on my lap, feeling very lucky.",
      "<mark class=\"c\">At the next station,</mark> the doors slid open and an elderly woman shuffled in. <mark class=\"sh\">She was carrying two heavy plastic bags of vegetables, and her thin arms shook as she grabbed the pole.</mark> Nobody moved. A man in a suit stared at his phone. Two teenagers kept their eyes shut.",
      "I looked at my comfortable seat. <mark class=\"f\">I was tired</mark> after a long day of school and CCA, and my legs ached from netball practice. <mark class=\"sh\">I shifted in my seat and looked away, hoping someone else would stand up.</mark>",
      "<mark class=\"c\">Just then,</mark> the train jerked forward. The old woman wobbled, and one of her bags slipped. <mark class=\"fig\">Potatoes rolled across the floor like runaway marbles.</mark>",
      "That was enough. I jumped up. <mark class=\"d\">“Auntie, you can have my seat,” I said, pointing to it.</mark> Then, <mark class=\"id\">without a second thought</mark>, I scrambled after the potatoes.",
      "<mark class=\"d\">“Thank you, dear,” she said, lowering herself into the seat with a sigh. “My knees aren’t so good these days.”</mark>",
      "I dropped the last potato into her bag and handed it back to her. <mark class=\"sh\">She patted my hand, and her wrinkled face crinkled into a warm smile.</mark> <mark class=\"fig\">It was like watching the sun come out after a storm.</mark>",
      "<mark class=\"c\">For the rest of the journey,</mark> I stood holding the pole. My legs still ached, but <mark class=\"f\">I felt strangely light and happy</mark>. The old woman told me about her grandson, who was in Primary Four like me, and how she cooked his favourite soup every Friday.",
      "<mark class=\"c\">When she reached her stop,</mark> she waved at me through the window until the train pulled away. <mark class=\"sh\">I found myself grinning at my own reflection in the glass.</mark>",
      "That evening, I told Mum what had happened. <mark class=\"d\">“I’m proud of you,” she said. “It was only a seat, but it meant a lot to her.”</mark> I have never forgotten her words. <mark class=\"id\">A small act of kindness</mark> cost me a seat, but it gave me a feeling that lasted all week."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "A setting full of senses", text: "The opening puts us straight into a crowded train using touch, sound and sight. We feel how squashed it is." },
      { title: "An honest struggle", text: "The narrator does not stand up at once. Admitting she was tired and hoped someone else would help makes her kindness more real." },
      { title: "The turning point", text: "The rolling potatoes push the narrator to act. A small, believable event works better than something dramatic." },
      { title: "Showing the old woman’s feelings", text: "We see her shaking arms, her sigh and her crinkly smile. The writer never says “she was grateful”." },
      { title: "Meaningful ending", text: "Mum’s words sum up the lesson, and the last sentence contrasts what was lost (a seat) with what was gained (a good feeling)." }
    ] },
    { type: "essay", title: "An Act of Courage", level: "P5–P6", paras: [
      "It started with a laugh. <mark class=\"s\">A cruel, high-pitched laugh that echoed across the basketball court behind our block.</mark> I looked up from my bicycle and saw three older boys circling a small figure near the bench. It was Ravi, the quiet boy from my class who wore thick glasses and always sat alone at recess.",
      "<mark class=\"d\">“Four eyes! Can you even see the ball?” jeered the tallest boy, Marcus, snatching Ravi’s spectacles from his face.</mark>",
      "<mark class=\"sh\">Ravi squinted helplessly, his hands groping the air.</mark> The other boys tossed the glasses back and forth over his head <mark class=\"fig\">like a cruel game of monkey-in-the-middle</mark>.",
      "<mark class=\"sh\">My hands tightened around the handlebars. My mouth went dry.</mark> Marcus was in Secondary Two and <mark class=\"id\">a head taller than me</mark>. Everyone in the neighbourhood knew not to cross him. <mark class=\"f\">A wave of fear</mark> rooted me to the spot. <i>Just ride away,</i> a small voice in my head whispered. <i>It’s not your business.</i>",
      "<mark class=\"c\">But then</mark> Ravi stumbled and fell, grazing his knee on the rough ground. <mark class=\"sh\">He did not cry. He simply sat there, staring at nothing, as if he had given up.</mark> That was when I knew I could not ride away.",
      "I <mark class=\"id\">took a deep breath</mark> and walked my bicycle over. <mark class=\"sh\">My heart was hammering so hard that I was sure they could hear it.</mark>",
      "<mark class=\"d\">“Give them back,” I said. My voice came out smaller than I wanted, so I said it again, louder. “Give them back. Now.”</mark>",
      "Marcus turned and looked me up and down. <mark class=\"d\">“Or what?” he sneered.</mark>",
      "<mark class=\"d\">“Or I’ll call the security guard,” I replied, holding up my phone. “And I’ll tell your mother. She lives on the tenth floor, right?”</mark>",
      "<mark class=\"c\">For a long moment,</mark> nobody moved. <mark class=\"fig\">The silence stretched like a rubber band about to snap.</mark> <mark class=\"c\">Then</mark> Marcus rolled his eyes, tossed the glasses onto the bench and strolled off with his friends, muttering under his breath.",
      "<mark class=\"c\">With trembling fingers,</mark> I picked up the glasses and helped Ravi to his feet. <mark class=\"d\">“Thanks,” he mumbled, wiping the lenses on his shirt. “Nobody’s ever done that for me before.”</mark>",
      "Those words stayed with me all the way home. <mark class=\"c\">From that day on,</mark> Ravi and I sat together at recess, and I discovered that the quiet boy had the funniest jokes in the class.",
      "I learnt that courage is not the absence of fear. <mark class=\"f\">I was terrified</mark> the whole time. Courage is being afraid and <mark class=\"id\">standing up for what is right</mark> anyway."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "A sound hook", text: "The story begins with a cruel laugh, which makes the reader ask, “Who is laughing, and why?”" },
      { title: "Inner voice", text: "The narrator’s thoughts are written in italics (“Just ride away”). This shows the struggle between fear and doing the right thing." },
      { title: "Believable courage", text: "The narrator does not fight. He uses his head: he threatens to call the guard and the bully’s mother. This is realistic and safe." },
      { title: "Slowing down the climax", text: "Short paragraphs, short lines of dialogue and the “rubber band” simile stretch out the tense moment." },
      { title: "Character change", text: "The ending shows a new friendship, so the act of courage has a lasting result." },
      { title: "A thoughtful reflection", text: "The last paragraph gives a fresh definition of courage instead of a plain “I learnt to be brave”." }
    ] },
    { type: "essay", title: "A Mistake and an Apology", level: "P5–P6", paras: [
      "<mark class=\"s\">The ceramic owl sat on Grandma’s shelf, its painted eyes glinting in the afternoon light.</mark> It was small, chipped at one ear and, to me, rather ugly. <mark class=\"c\">But</mark> Grandma loved it more than anything else in her flat. Grandpa had bought it for her on their honeymoon fifty years ago.",
      "<mark class=\"d\">“Don’t play ball in the living room,” Grandma warned as she left for the market. “And watch the owl!”</mark>",
      "<mark class=\"d\">“Okay, Grandma!” my cousin Jia Hui and I chorused.</mark> <mark class=\"c\">But the moment the door clicked shut,</mark> Jia Hui pulled a tennis ball out of her pocket and <mark class=\"sh\">raised her eyebrows at me with a cheeky grin</mark>.",
      "<mark class=\"c\">At first,</mark> we threw it gently. <mark class=\"c\">Soon,</mark> we were throwing it harder and higher, giggling every time one of us missed. I leapt for a wild throw, <mark class=\"c\">and then</mark> <mark class=\"s\">I heard it: a sharp crack, followed by a tinkling crash.</mark>",
      "<mark class=\"sh\">My stomach dropped.</mark> The owl lay on the floor in three pieces. <mark class=\"fig\">Its single remaining eye stared up at me, as if it were accusing me.</mark>",
      "<mark class=\"d\">“We’re in big trouble,” Jia Hui whispered.</mark>",
      "<mark class=\"d\">“We could glue it,” I said quickly. “She might not notice.”</mark>",
      "We found some superglue in a drawer and <mark class=\"sh\">worked in tense silence, our fingers sticky and shaking</mark>. When we finished, the owl looked almost whole, if you did not look too closely. I placed it back on the shelf, turning the cracks towards the wall.",
      "When Grandma came home, <mark class=\"sh\">I could not look her in the eye</mark>. All through dinner, <mark class=\"fig\">guilt sat in my stomach like a heavy stone</mark>. Every time she glanced at the shelf, <mark class=\"sh\">my heart skipped a beat</mark>.",
      "<mark class=\"c\">That night,</mark> I could not sleep. I kept picturing Grandma finding the cracks one day and thinking someone had lied to her. <mark class=\"c\">Finally,</mark> I <mark class=\"id\">plucked up the courage</mark> and tiptoed to her room.",
      "<mark class=\"d\">“Grandma,” I said, my voice wobbling, “I broke your owl. We were playing ball in the living room. I tried to glue it, but… I should have told you. I’m so sorry.”</mark>",
      "<mark class=\"sh\">Grandma was quiet for a long time. Then she took the owl from the shelf, turned it slowly in her hands and traced the cracks with her thumb.</mark>",
      "<mark class=\"d\">“I’m sad it’s broken,” she said softly. “But I’m glad you told me the truth.”</mark> She pulled me into a hug. <mark class=\"f\">Relief washed over me</mark>, and I burst into tears.",
      "The owl still sits on Grandma’s shelf, cracks and all. Every time I see it, I remember that <mark class=\"id\">owning up to a mistake</mark> is hard, but hiding it is much harder."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "An object at the centre", text: "The owl is introduced in the first paragraph with its back story. Because we know why it matters, we feel the shock when it breaks." },
      { title: "Building up step by step", text: "“At first… Soon… and then” shows the game getting rougher, so the accident feels like a natural result." },
      { title: "Two mistakes, not one", text: "Breaking the owl is the first mistake; hiding it is the second. This gives the narrator a real problem to solve." },
      { title: "Guilt shown, not told", text: "Not looking Grandma in the eye, a heart that skips and a stone in the stomach all show guilt clearly." },
      { title: "A gentle, honest apology", text: "The apology is in the narrator’s own wobbly words, and Grandma’s quiet reaction makes the moment powerful." },
      { title: "Circular ending", text: "The story ends where it began, with the owl on the shelf, but now it carries a lesson." }
    ] },
    { type: "essay", title: "The Spelling Bee", level: "P3–P4", paras: [
      "<mark class=\"s\">The school hall was so quiet that I could hear the ceiling fans whirring and a chair creaking somewhere at the back.</mark> Only two of us were left on the stage: Jun Hao from 4B and me.",
      "<mark class=\"c\">For weeks,</mark> I had practised for this spelling bee. Every night after dinner, Dad read out words from a long list while I paced up and down the living room. <mark class=\"id\">Practice makes perfect</mark>, he always said.",
      "<mark class=\"d\">“Kelly, your word is ‘necessary’,” announced Mrs Tan.</mark>",
      "<mark class=\"sh\">My palms turned sweaty. I wiped them on my skirt and closed my eyes.</mark> One collar, two sleeves, I reminded myself. <mark class=\"d\">“N-E-C-E-S-S-A-R-Y,” I spelt slowly.</mark>",
      "<mark class=\"d\">“Correct!”</mark> <mark class=\"s\">The audience clapped, and I heard my best friend, Aisha, cheer loudly from the third row.</mark>",
      "Jun Hao stepped forward. He spelt ‘rhythm’ perfectly, <mark class=\"sh\">without even blinking</mark>. <mark class=\"f\">My heart sank.</mark> He was good. Very good.",
      "<mark class=\"c\">Round after round,</mark> neither of us made a mistake. <mark class=\"c\">Then</mark> Mrs Tan read out my next word: <mark class=\"d\">“Kelly, please spell ‘embarrass’.”</mark>",
      "<mark class=\"sh\">My mind went blank.</mark> Was it one r or two? One s or two? <mark class=\"fig\">The letters swirled in my head like leaves in a storm.</mark> I took a deep breath and guessed. <mark class=\"d\">“E-M-B-A-R-A-S-S.”</mark>",
      "<mark class=\"d\">“I’m sorry, that’s not right,” Mrs Tan said gently.</mark>",
      "<mark class=\"sh\">My cheeks burned.</mark> Jun Hao spelt the word correctly and then spelt one more to win. The hall burst into applause. <mark class=\"f\">I felt disappointed</mark>, but when Jun Hao walked over and held out his hand, I shook it and smiled.",
      "<mark class=\"d\">“You were really good,” he said. “I was sure you were going to win!”</mark>",
      "<mark class=\"c\">On the way home,</mark> Dad bought me my favourite ice kachang. <mark class=\"d\">“Second place out of the whole level,” he said, beaming. “I’m so proud of you.”</mark>",
      "I did not win the trophy that day, but I won something else: a new friend and the knowledge that I could stand on a stage without running away. And I will never spell ‘embarrass’ wrongly again!"
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "Start at an exciting moment", text: "The story opens in the final round, not on the morning of the competition. Then it quickly flashes back to the weeks of practice." },
      { title: "Use real details", text: "The spelling trick (“one collar, two sleeves”) and the real words make the competition feel true." },
      { title: "Show nerves", text: "Sweaty palms, a blank mind and burning cheeks show the narrator’s feelings at each stage." },
      { title: "Losing well", text: "The narrator does not win, but shakes hands and smiles. A story about a competition does not need a victory to be satisfying." },
      { title: "A light ending", text: "The last line adds a touch of humour and links back to the word she got wrong." }
    ] },
    { type: "essay", title: "An Unexpected Accident at Home", level: "P5–P6", paras: [
      "<mark class=\"s\">Sizzle! The smell of garlic and frying eggs filled our small kitchen</mark> as I stood on tiptoe beside Mum, watching her cook. It was Sunday morning, and she had promised to teach me how to make fried rice.",
      "<mark class=\"d\">“Stand back a little,” Mum said, tilting the wok. “The oil is very hot.”</mark>",
      "<mark class=\"c\">Just then,</mark> her phone rang in the living room. <mark class=\"d\">“Watch the wok for one minute. Don’t touch anything,” she called, hurrying out.</mark>",
      "<mark class=\"c\">At first,</mark> I simply watched the rice. <mark class=\"c\">But</mark> the sizzling grew louder and the smell began to change. <mark class=\"s\">A thin line of grey smoke curled up from the wok, and the rice at the bottom started to blacken.</mark> <mark class=\"sh\">I bit my lip.</mark> Mum had said not to touch anything, but surely I could stir it?",
      "I grabbed the spatula and pushed the rice around. <mark class=\"c\">In my hurry,</mark> my elbow knocked the handle of the wok. <mark class=\"s\">Hot oil splashed out with a loud hiss</mark>, and a few drops landed on the gas flame. <mark class=\"fig\">In an instant, orange flames leapt up like angry tongues, licking at the cooker hood.</mark>",
      "<mark class=\"d\">“Mum!” I screamed.</mark> <mark class=\"sh\">I stumbled backwards, my heart pounding so hard that my chest hurt.</mark>",
      "Mum <mark class=\"id\">was at my side in a flash</mark>. <mark class=\"sh\">Without a word, she turned off the gas, grabbed the wok lid and slammed it down over the flames.</mark> <mark class=\"s\">The fire hissed, spat and then died.</mark> <mark class=\"s\">The kitchen was filled with the bitter smell of burnt rice and smoke.</mark>",
      "<mark class=\"c\">For a moment,</mark> neither of us spoke. <mark class=\"sh\">Then Mum knelt down, took my hands and checked them carefully, turning them over and over.</mark> A small red spot glowed on my wrist where a drop of oil had landed.",
      "<mark class=\"d\">“Are you hurt anywhere else?”</mark> she asked, her voice shaking. I shook my head, <mark class=\"sh\">tears spilling down my cheeks</mark>. She held my wrist under cool running water for a long time, <mark class=\"c\">while</mark> I sobbed out an apology.",
      "<mark class=\"d\">“I’m not angry,” she said, hugging me tightly. “I shouldn’t have left you alone at the stove. But remember, never pour water on an oil fire. Turn off the gas and cover it.”</mark>",
      "We ate bread for lunch that day. The scar on my wrist has faded now, but <mark class=\"f\">the fright</mark> of that morning has not. I still help Mum in the kitchen, <mark class=\"c\">but</mark> I <mark class=\"id\">never take my eyes off</mark> a hot stove, and I always ask before I touch anything."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "Sound and smell first", text: "The story opens with “Sizzle!” and the smell of garlic. Later, the smell changes to burning, which warns the reader that trouble is coming." },
      { title: "A warning that is ignored", text: "Mum’s instruction “Don’t touch anything” sets up the problem. The reader knows what might happen before it does." },
      { title: "A clear cause", text: "The accident happens because of a small, realistic mistake: an elbow knocking the wok. Accident stories work best when the cause is clear." },
      { title: "Slow, careful climax", text: "Mum’s actions are described one at a time (gas, lid, flames), so the reader can follow exactly how the fire was put out." },
      { title: "Safe, accurate details", text: "The story shows the right thing to do with an oil fire and with a small burn. Good accident stories are careful, not gory." },
      { title: "Lesson through action", text: "Instead of “I learnt to be careful”, the ending tells us what the narrator now does differently." }
    ] }
  ] },
{ id: "en-upgrade", group: "Model essays", order: 62, title: "Upgrade an essay",
  intro: "See how a plain story can become a great one. Each pair shows the same story twice: first a weak version, then an upgraded version. Read the notes to learn exactly what changed.",
  blocks: [
    { type: "tip", html: "<b>Tip:</b> Upgrading is not about using longer words. It is about adding the right details, showing feelings, slowing down the important moment and cutting out the boring parts." },
    { type: "essay", title: "Lost at the Zoo (before)", level: "P3–P4", paras: [
      "One day, my family and I went to the zoo. We went there by car. It was a sunny day. I was very happy.",
      "We saw many animals. We saw the monkeys and the elephants and the giraffes. They were very nice. <mark class=\"c\">Then</mark> we went to see the tigers.",
      "When I turned around, my parents were gone. I was very scared. I looked everywhere but I could not find them. I cried.",
      "A zoo keeper saw me. She asked me what happened. I told her I was lost. She helped me find my parents. They were at the gift shop.",
      "My mother hugged me. I was very happy. I learnt that I should not wander off. It was a very good day."
    ], legend: [
      { cls: "c", label: "Connectors" }
    ], notes: [
      { title: "Boring opening", text: "“One day” and “We went there by car” do not hook the reader. The car journey does not matter to the story." },
      { title: "Listing, not describing", text: "The animals are just a list (“monkeys and elephants and giraffes”) with the vague word “nice”. No senses are used." },
      { title: "Feelings are told", text: "“I was very happy”, “I was very scared”: the reader is told how the narrator feels instead of being shown." },
      { title: "Climax is rushed", text: "The most important part (getting lost) is only four short sentences. There is no tension and no dialogue." },
      { title: "Flat ending", text: "“It was a very good day” does not fit a story about getting lost, and the lesson is stated without feeling." }
    ] },
    { type: "essay", title: "Lost at the Zoo (after)", level: "P3–P4", paras: [
      "<mark class=\"s\">Whoop! Whoop! The orang utans swung from rope to rope above our heads</mark>, and I <mark class=\"f\">squealed with delight</mark>. It was the first time I had been to the zoo, and I wanted to see everything.",
      "<mark class=\"c\">After lunch,</mark> we headed to the white tiger enclosure. <mark class=\"s\">A huge tiger padded along the rocks, its striped fur gleaming in the sun.</mark> I pressed my nose against the glass, <mark class=\"sh\">too amazed to blink</mark>.",
      "<mark class=\"c\">When I finally turned around,</mark> Mum and Dad were gone. <mark class=\"s\">All I could see was a sea of strangers’ legs and the bright colours of their T-shirts.</mark> <mark class=\"sh\">My throat tightened. I spun around, searching every face.</mark>",
      "<mark class=\"d\">“Mum? Dad?” I called. My voice came out as a squeak.</mark> Nobody answered. <mark class=\"fig\">My heart thumped like a drum</mark>, and hot tears blurred my eyes.",
      "<mark class=\"c\">Just then,</mark> a zookeeper in a green uniform knelt beside me. <mark class=\"d\">“Are you lost?” she asked gently. “Don’t worry. We’ll find your mum and dad.”</mark> She spoke into her walkie-talkie, and soon a voice crackled back.",
      "<mark class=\"c\">Ten minutes later,</mark> I saw Mum running towards me, her face pale. <mark class=\"sh\">She swept me into her arms and held me so tightly that I could hardly breathe.</mark> <mark class=\"d\">“Don’t ever wander off like that again,”</mark> she whispered, her voice shaking.",
      "<mark class=\"f\">Relieved</mark>, I buried my face in her shoulder. <mark class=\"c\">From that day on,</mark> I always held Mum’s hand in crowded places, and I never let a tiger distract me again!"
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }
    ], notes: [
      { title: "A sound hook", text: "The story now starts with the orang utans’ calls, putting the reader right in the zoo. The car ride has been cut." },
      { title: "One animal, described well", text: "Instead of listing animals, the writer describes ONE tiger in detail. This also explains why the narrator got lost." },
      { title: "Feelings shown", text: "A tight throat, a thumping heart and blurry eyes replace “I was very scared”." },
      { title: "Climax slowed down", text: "Getting lost now takes three paragraphs, with dialogue and actions, so the reader feels worried too." },
      { title: "A fitting ending", text: "The lesson is shown through what the narrator does afterwards, with a small joke about the tiger." }
    ] },
    { type: "essay", title: "Helping a Neighbour (before)", level: "P5–P6", paras: [
      "Last week, something happened that I will never forget. I was walking home from school. It was raining. I saw an old lady at the void deck.",
      "She had fallen down. Her groceries were all over the floor. She looked very sad and in pain. I felt sorry for her.",
      "I went to help her. I picked up her things. I asked her if she was ok and she said her leg was painful. <mark class=\"c\">So</mark> I called my mum and my mum came down. My mum called the ambulance.",
      "The ambulance came and took her to the hospital. The next day we visited her. She was very happy to see us. She said thank you many times.",
      "<mark class=\"c\">In conclusion</mark>, I learnt that we should always help others. Helping others is very important. I felt very proud of myself."
    ], legend: [
      { cls: "c", label: "Connectors" }
    ], notes: [
      { title: "Tells instead of starts", text: "“Something happened that I will never forget” is a common opening that does not show us anything." },
      { title: "Choppy sentences", text: "Many short sentences in a row (“I was walking… It was raining… I saw…”) make the writing sound like a list." },
      { title: "Weak setting", text: "The rain is mentioned but not used. We cannot see, hear or feel it." },
      { title: "No dialogue", text: "“I asked her if she was ok” is reported speech. Real dialogue would bring the old lady to life." },
      { title: "Essay-style ending", text: "“In conclusion” belongs in a report, not a story. The lesson is repeated twice without any feeling." }
    ] },
    { type: "essay", title: "Helping a Neighbour (after)", level: "P5–P6", paras: [
      "<mark class=\"s\">Rain hammered on the covered walkway outside the void deck, and puddles spread across the cracked floor.</mark> I was shaking water off my umbrella <mark class=\"c\">when</mark> I heard a faint cry.",
      "Near the lift lobby, an elderly woman lay on the wet tiles. <mark class=\"s\">Oranges had rolled in every direction, and a bag of rice had split open, scattering white grains across the floor.</mark> <mark class=\"sh\">She was clutching her ankle, her face twisted in pain.</mark> I recognised her at once. It was Madam Wong from the seventh floor, who always gave me sweets at Chinese New Year.",
      "<mark class=\"c\">Without a second thought,</mark> I dropped my bag and rushed over. <mark class=\"d\">“Madam Wong, are you all right?” I asked, kneeling beside her.</mark>",
      "<mark class=\"d\">“I slipped,” she gasped. “My ankle… I can’t get up.”</mark>",
      "<mark class=\"sh\">My mind raced.</mark> I knew I should not try to lift her. <mark class=\"c\">Instead,</mark> I pulled off my jacket, folded it and slid it gently under her head. <mark class=\"c\">Then,</mark> <mark class=\"sh\">with trembling fingers,</mark> I dialled Mum’s number.",
      "<mark class=\"d\">“Mum, come down quickly! Madam Wong has fallen at the void deck!”</mark>",
      "<mark class=\"c\">Within minutes,</mark> Mum came running, still in her slippers. She took one look at the swollen ankle and called 995. <mark class=\"c\">While we waited,</mark> I gathered the oranges and held Madam Wong’s cold, wrinkled hand. <mark class=\"sh\">She squeezed my fingers tightly each time the pain came.</mark>",
      "<mark class=\"s\">When the siren finally wailed into the car park</mark>, <mark class=\"f\">relief flooded through me</mark>. The paramedics lifted her carefully onto a stretcher. <mark class=\"sh\">Before they wheeled her away, she turned her head and gave me a weak but grateful smile.</mark>",
      "The next afternoon, Mum and I visited her in hospital with a bag of fresh oranges. <mark class=\"d\">“You’re my little hero,” she said, patting my cheek.</mark> <mark class=\"sh\">My face grew warm, but inside I was glowing.</mark>",
      "Now, whenever I pass the lift lobby, I remember that rainy afternoon. <mark class=\"id\">Lending a helping hand</mark> did not take much, but to Madam Wong, it meant everything."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "Setting with senses", text: "The rain now hammers, puddles spread and a faint cry pulls us into the action." },
      { title: "A real neighbour", text: "The old lady is now Madam Wong, with a small back story. Readers care more about a named person." },
      { title: "Sensible, believable help", text: "The narrator does not try to lift her, but makes her comfortable and calls an adult. This is realistic and shows good judgement." },
      { title: "Varied sentences and connectors", text: "Connectors such as “Without a second thought”, “Instead” and “While we waited” link the actions smoothly." },
      { title: "Real dialogue", text: "Short, natural lines of speech replace reported speech and add urgency." },
      { title: "A warm ending", text: "No “In conclusion”. The ending links back to the place and uses a good phrase to sum up the meaning." }
    ] },
    { type: "essay", title: "My Best Friend’s Birthday (before)", level: "P3–P4", paras: [
      "It was my best friend’s birthday. Her name is Mei Ling. I wanted to buy her a present but I did not have enough money.",
      "<mark class=\"c\">So</mark> I decided to make her a present. I made her a card and a bracelet. It took me a long time. It was very hard.",
      "On her birthday I gave her the present. She opened it. She liked it very much. She said it was the best present.",
      "I was very happy that she liked it. The end."
    ], legend: [
      { cls: "c", label: "Connectors" }
    ], notes: [
      { title: "No problem worth reading", text: "The problem (not enough money) is mentioned but never felt. The reader does not worry about it." },
      { title: "Skips the interesting part", text: "Making the gift is the heart of the story, but it is summed up as “It took me a long time. It was very hard.”" },
      { title: "Vague words", text: "“A card and a bracelet” and “liked it very much” give no details for the reader to picture." },
      { title: "“The end”", text: "Never end with “The end”. Finish with a thought, a feeling or a memorable action instead." }
    ] },
    { type: "essay", title: "My Best Friend’s Birthday (after)", level: "P3–P4", paras: [
      "<mark class=\"sh\">I tipped my piggy bank upside down and shook it hard.</mark> <mark class=\"s\">Three coins clinked onto the bed.</mark> One dollar and forty cents. <mark class=\"f\">My heart sank.</mark> Mei Ling’s birthday was in two days, and the unicorn pencil case she wanted cost fifteen dollars.",
      "<mark class=\"c\">Then</mark> I had an idea. Mei Ling’s favourite colour was purple, and she loved anything that sparkled. <mark class=\"c\">That evening,</mark> I dug out my craft box and got to work.",
      "<mark class=\"c\">First,</mark> I threaded tiny purple and silver beads onto a string to make a bracelet. <mark class=\"sh\">My fingers ached, and twice the string snapped, sending beads bouncing across the floor.</mark> <mark class=\"d\">“Oh no!” I groaned, crawling under the table to find them.</mark> <mark class=\"c\">Next,</mark> I made a pop-up card with a paper cake that jumped up when you opened it. I wrote a poem inside about all the fun we had at recess.",
      "<mark class=\"c\">On the morning of her birthday,</mark> <mark class=\"sh\">I held the little parcel behind my back, my stomach fluttering.</mark> What if she thought it was babyish?",
      "Mei Ling tore off the wrapping paper. When the paper cake popped up, she gasped. <mark class=\"c\">Then</mark> she slipped the bracelet onto her wrist and held it up to the light. <mark class=\"fig\">The beads sparkled like tiny stars.</mark>",
      "<mark class=\"d\">“You made this? For me?” she whispered. “It’s the best present ever!”</mark> She threw her arms around me.",
      "<mark class=\"c\">Even now,</mark> Mei Ling wears that bracelet every day. Whenever I see it glinting on her wrist, I remember that <mark class=\"id\">the best gifts come from the heart</mark>, not from the shop."
    ], legend: [
      { cls: "s", label: "Five senses" }, { cls: "sh", label: "Show, don’t tell" }, { cls: "f", label: "Feeling words" },
      { cls: "d", label: "Dialogue" }, { cls: "c", label: "Connectors" }, { cls: "fig", label: "Figurative language" }, { cls: "id", label: "Good phrases" }
    ], notes: [
      { title: "Start with the problem", text: "The piggy bank scene shows the problem with an action, a sound and a number, so we feel the narrator’s disappointment." },
      { title: "Expand the key part", text: "Making the gift now has steps (First, Next), a setback (the string snapping) and a funny moment." },
      { title: "Specific details", text: "Purple and silver beads, a pop-up paper cake and a poem about recess: the reader can picture every part of the gift." },
      { title: "A moment of doubt", text: "“What if she thought it was babyish?” adds a little tension just before the gift is opened." },
      { title: "A strong final line", text: "Instead of “The end”, the story finishes with a lasting image and a good phrase that sums up the message." }
    ] },
    { type: "rewrite", title: "Upgrade this paragraph", intro: "Each paragraph is plain and tells too much. Rewrite it using senses, show-don’t-tell, a strong verb or two, and dialogue where it fits. Then compare with the model.", items: [
      { q: "I went to the hawker centre with my family. It was very crowded. The food was very nice. I ate chicken rice.", a: "The hawker centre was buzzing with the clatter of plates and the shouts of busy uncles. We squeezed between the tables until Dad spotted an empty one. Soon, a steaming plate of chicken rice sat in front of me, the tender chicken glistening with sesame oil. I gobbled every grain.", hint: "Add sounds and describe the food so the reader can taste it." },
      { q: "The weather was bad. It rained heavily. I was wet. I was cold.", a: "Dark clouds swallowed the sun, and within seconds the rain came down in sheets. By the time I reached the bus stop, my uniform was clinging to my skin. I hugged my arms tightly as my teeth chattered.", hint: "Show the cold through the body." },
      { q: "My friend was angry with me. She did not talk to me. I felt sad.", a: "Aisha stomped past my desk without a glance. When I said hello at recess, she turned her back and walked away. A lump rose in my throat, and my sandwich suddenly tasted like cardboard." },
      { q: "I won the race. Everyone clapped. I was very happy and proud.", a: "I burst through the finishing tape a split second ahead of Jun Hao. The crowd erupted into cheers. Grinning from ear to ear, I punched the air and searched the stands for Mum, who was jumping up and down and waving her hat." },
      { q: "I was scared because there was a sound outside my room. I went to see. It was my cat.", a: "Scratch, scratch, scratch. I froze under my blanket, my heart thumping. Something was outside my door. Gathering every bit of courage, I crept across the room and flung the door open. Two green eyes blinked up at me. “Mimi!” I laughed, scooping up my cat." },
      { q: "My grandmother is kind. She cooks for us. She is old.", a: "Grandma’s silver hair is always tied in a neat bun, and her hands are soft and wrinkled. Every Sunday, she spends the whole morning in the kitchen, stirring a big pot of chicken soup. “Eat more. You’re too thin,” she says, piling more rice onto my plate." },
      { q: "The classroom was noisy. The teacher came in. Everyone was quiet.", a: "Chairs scraped, paper planes flew and someone was singing at the back. Then the door swung open. Mrs Lee stood there with her arms folded. In an instant, the room fell so silent that we could hear the fan whirring." },
      { q: "I broke the vase. My mother was angry. I said sorry.", a: "Crash! The vase lay in pieces on the floor. Mum rushed in, and her eyes narrowed as she saw the shards. “Who did this?” she asked sharply. My cheeks burned. “I’m sorry, Mum,” I mumbled, staring at my feet. “I was playing with the ball.”" },
      { q: "We went to the beach. It was fun. We built a sandcastle. Then we went home.", a: "The warm sand squished between my toes as we raced towards the sea. My brother and I spent the whole afternoon building a sandcastle with four towers and a moat. Just as we finished, a wave crept up and swallowed it whole. We laughed so hard that we fell over." },
      { q: "I was nervous before my piano exam. I played well. I passed.", a: "Outside the exam room, I flexed my cold fingers again and again. When my name was called, my legs felt like jelly. But as soon as I touched the keys, the music flowed out just as I had practised. Two weeks later, when the result arrived, I let out a squeal: I had passed with merit!" }
    ] }
  ] }
] });
